const tabela = (cab, linhas, vazio) => `<section class="cx rolo"><table><thead><tr>${cab.map((c) => (c.startsWith('$') ? `<th class="dir">${c.slice(1)}</th>` : `<th>${c}</th>`)).join('')}</tr></thead><tbody>${linhas.join('') || `<tr><td colspan="${cab.length}" style="color:var(--tx-3)">${vazio}</td></tr>`}</tbody></table></section>`;
