  contestar: (d) => { const y = db.repasses.find((z) => z.id === d.id); janela(`Contestar glosa · ${x(y.prog)}`, `<p style="color:var(--tx-3)">${R$(y.glosa)} · ${x(y.motivo)}</p>${campo('Justificativa', inp('j', '', 'required placeholder="Receita e cupom anexados; CRM do médico conferido"'))}`, 'Enviar contestação', (f) => { const j = String(f.get('j')).trim(); if (j.length < 10) return 'Explique com pelo menos 10 letras.'; y.contestada = j; anota(`contestou ${R$(y.glosa)} de glosa do ${y.prog}`); }); },
